import React, { useState } from 'react';

import List from '@mui/material/List';
import ListItem from '@mui/material/ListItem';
import ListItemAvatar from '@mui/material/ListItemAvatar';
import ListItemText from '@mui/material/ListItemText';

import { Box, Button, Step, StepLabel, Stepper, Tooltip, Typography } from '@mui/material';

import YoutubeIcon from '@mui/icons-material/YouTube';

export default function Contact() {

  const items= [
    {
      title: "Batched Support",
      description: "Youtube Demonstrations",
      src: "https://www.youtube.com/embed/videoseries?list=PLh17cpqc5tdVTfkuoQAFbqlHHm0RBA6cO",
      steps: ['Step 1', 'Step 2', 'Step 3'],
    },
    {
      title: "Mohawk College",
      description: "TeaBank Capstone Final Demonstration",
      src: "https://www.youtube.com/embed/aFiUmvcF3Xw?si=RbzuFhUhqu5qPJsA",
      steps: ['Step 1', 'Step 2', 'Step 3'],
    },
    {
      title: "Mohawk College",
      description: "PHP Demonstrations",
      src: "https://www.youtube.com/embed/videoseries?list=PLh17cpqc5tdWh_b2x-6Am0r08BeYy0H2g",
      steps: ['Step 1', 'Step 2', 'Step 3'],
    },
    {
      title: "Mohawk College",
      description: "Mohawk College Technical Presentations",
      src: "https://www.youtube.com/embed/videoseries?list=PLh17cpqc5tdUla07BUe_gP5kNb0sowuh_",
      steps: ['Step 1', 'Step 2', 'Step 3'],
    },
  ];

  const youtubeWidth = window.innerWidth > 600 ? "50%" : "100%";
  const youtubeHeight = window.innerWidth > 600 ? "50vh" : "30vh";
  
  const [activeSteps, setActiveSteps] = useState<number[]>(items.map(() => 0));
  const [skippedSteps, setSkippedSteps] = useState<Set<number>>(new Set());
  
  const isStepOptional = (step: number) => {
    return step === 1;
  };

  const isStepSkipped = (step: number) => {
    return skipped.has(step);
  };

  const handleNext = () => {
    let newSkipped = skipped;
    if (isStepSkipped(activeStep)) {
      newSkipped = new Set(newSkipped.values());
      newSkipped.delete(activeStep);
    }

    setActiveStep((prevActiveStep) => prevActiveStep + 1);
    setSkipped(newSkipped);
  };

  const handleBack = () => {
    setActiveStep((prevActiveStep) => prevActiveStep - 1);
  };

  const handleSkip = () => {
    if (!isStepOptional(activeStep)) {
      // You probably want to guard against something like this,
      // it should never occur unless someone's actively trying to break something.
      throw new Error("You can't skip a step that isn't optional.");
    }

    setActiveStep((prevActiveStep) => prevActiveStep + 1);
    setSkipped((prevSkipped) => {
      const newSkipped = new Set(prevSkipped.values());
      newSkipped.add(activeStep);
      return newSkipped;
    });
  };

  const handleReset = () => {
    setActiveStep(0);
  };

  return (
      <>
      <List dense={false}>
          {items.map((item, index) => (
      <ListItem
        key={index}
        sx={{
          backgroundColor: index % 2 === 0 ? "#f9f9f9" : "#eaeaea", // Alternate background colors
          borderRadius: "8px",
          marginBottom: "16px",
        }}
      >
        <ListItemAvatar>
          <YoutubeIcon sx={{color: "#FF0000"}}/>
        </ListItemAvatar>
        <ListItemText primary={item.title} secondary={item.description} />
        <Box sx={{ width: '100%' }}>
          <Stepper key={`stepper-${index}`} activeStep={activeStep}>
            {item.steps.map((label, index) => {
              const stepProps: { completed?: boolean } = {};
              const labelProps: {
                optional?: React.ReactNode;
              } = {};
              if (isStepOptional(index)) {
                labelProps.optional = (
                  <Typography variant="caption">Optional</Typography>
                );
              }
              if (isStepSkipped(index)) {
                stepProps.completed = false;
              }
              return (
                <Step key={`step-${index}`} {...stepProps}>
                  <StepLabel {...labelProps}>{label}</StepLabel>
                </Step>
              );
            })}
          </Stepper>
          {activeStep === item.steps.length ? (
            <React.Fragment>
              <Typography sx={{ mt: 2, mb: 1 }}>
                All steps completed - you&apos;re finished
              </Typography>
              <Box sx={{ display: 'flex', flexDirection: 'row', pt: 2 }}>
                <Box sx={{ flex: '1 1 auto' }} />
                <Button onClick={handleReset}>Reset</Button>
              </Box>
            </React.Fragment>
          ) : (
            <React.Fragment>
              <Typography sx={{ mt: 2, mb: 1 }}>Step {activeStep + 1}</Typography>
              <Box sx={{ display: 'flex', flexDirection: 'row', pt: 2 }}>
                <Button
                  key={`back-button-${index}`}
                  color="inherit"
                  disabled={activeStep === 0}
                  onClick={handleBack}
                  sx={{ mr: 1 }}
                >
                  Back
                </Button>
                <Box sx={{ flex: '1 1 auto' }} />
                {isStepOptional(activeStep) && (
                  <Button
                    key={`skip-button-${index}`}
                    color="inherit"
                    onClick={handleSkip}
                    sx={{ mr: 1 }}
                  >
                    Skip
                  </Button>
                )}
                <Button
                  key={`next-button-${index}`}
                  onClick={handleNext}
                >
                  {activeStep === item.steps.length - 1 ? 'Finish' : 'Next'}
                </Button>
              </Box>
            </React.Fragment>
          )}
        </Box>
        {/* <Tooltip title={`Play: ${item.src}?`} arrow>
          <Box
            sx={{
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              width: youtubeWidth,
              height: { sm: '25vw' },
            }}
          >
            <iframe
              src={item.src}
              title="YouTube video player"
              style={{
                borderRadius: "8px",
                width: "100%",
                height: "100%",
              }}
              frameBorder="0"
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
              allowFullScreen
            ></iframe>
          </Box>
        </Tooltip> */}
      </ListItem>
      ))}
      </List>
      </>
  )
}
